a = int(input('Enter a: '))
b = int(input('Enter b: '))
c = int(input('Enter c: '))
if a >= b and a >= c:
    print('Largest:', a)
elif b >= c:
    print('Largest:', b)
else:
    print('Largest:', c)

n = int(input('Enter number: '))
if n < 2:
    print('Neither prime nor composite')
else:
    is_prime = True
    for i in range(2, n):
        if n % i == 0:
            is_prime = False
            break
    if is_prime:
        print('Prime')
    else:
        print('Composite')

n = int(input('Enter number: '))
temp, rev = n, 0
while temp > 0:
    rev = rev * 10 + temp % 10
    temp //= 10
if rev == n:
    print('Palindrome')
else:
    print('Not Palindrome')

n = int(input('Enter number: '))
d = len(str(n))
temp, total = n, 0
while temp > 0:
    total += (temp % 10) ** d
    temp //= 10
if total == n:
    print('Armstrong')
else:
    print('Not Armstrong')

n = int(input('Enter number: '))
s = 0
for i in range(1, n):
    if n % i == 0:
        s += i
if s == n:
    print('Perfect')
else:
    print('Not Perfect')

