s = input('Enter string: ')
v = c = up = lo = 0
for ch in s:
    if ch.isalpha():
        if ch.lower() in 'aeiou':
            v += 1
        else:
            c += 1
        if ch.isupper():
            up += 1
        else:
            lo += 1
print('Vowels:', v, 'Consonants:', c)
print('Uppercase:', up, 'Lowercase:', lo)

